from maths_notes_v4.kit4 import H, I, Y, X, K, L, BK, Ex, mcq, grid

READ = {}

# =====================================================================================================
# 1.1 What is science? · 7SIC.01
# =====================================================================================================
READ["1.1"] = L(
    H("A wet glass on a dry day",
      "Take a glass of ice-cold water out of the fridge and leave it on the table. After a few minutes the **outside** of the glass is wet, "
      "even though no water has spilled.",
      "Where did that water come from? Write down your best idea before you read on. A careful, testable idea like yours is where science begins.",
      fig={"kind": "sciGlass"}),
    I("What is science?",
      "**Science** is the study of how the natural world works, and of why things happen the way they do.",
      "Anything we can observe happening is called a **phenomenon** (plural: **phenomena**): ice melting, a seed growing, a rainbow after a storm, a phone screen lighting up.",
      "Science has **two parts**:",
      table=[["Part of science", "What it means", "Example"],
             ["What we already know", "explanations that have been tested again and again", "water vapour in the air turns back into liquid water when it touches something cold"],
             ["How we find out more", "asking questions, making predictions, doing fair tests and looking at the evidence", "putting a cold glass and a warm glass side by side and watching which one gets wet"]],
      fig={"kind": "sciParts"}),
    I("Back to the wet glass",
      "The air around us always holds some **water vapour** – water as an invisible gas.",
      "When the water vapour touches the cold glass, it cools down and **condenses**: it turns back into tiny drops of liquid water on the outside of the glass.",
      fig={"kind": "sciGlass", "labels": True},
      then=["So the wet glass is not a mystery. Science gave us the explanation – and a fair test with a cold glass and a warm glass lets us check it."]),
    I("Why does science matter?",
      "Look around you: almost everything you use was made possible by science.",
      fig={"kind": "sciImpact"},
      table=[["Part of daily life", "Science behind it", "A problem it has caused", "How science can help"],
             ["Electricity", "generating it in power stations, solar panels and wind turbines", "burning coal, oil and gas releases carbon dioxide", "better solar cells, batteries and wind turbines"],
             ["Materials", "plastics, steel, glass and new fabrics", "plastic waste in rivers and oceans", "plastics that break down, and better recycling"],
             ["Transport", "engines, fuels, aircraft and electric cars", "air pollution and global warming", "cleaner fuels and electric motors"],
             ["Medicine", "vaccines, antibiotics and X-ray machines", "some bacteria are no longer killed by antibiotics", "new medicines and careful use of old ones"]],
      then=["**Global warming** – the rise in the Earth's average temperature – is causing **climate change**. Science helped to cause some of these problems, "
            "and scientists are now working hard to solve them."]),
    I("Areas of study in science",
      "Science is a huge subject, so it is split into **areas of study**. Each area asks its own kind of question.",
      fig={"kind": "sciAreas"},
      table=[["Area of study", "It is the study of …", "A question it could answer"],
             ["Biology", "living things: plants, animals and microorganisms", "Why do leaves turn towards the light?"],
             ["Chemistry", "substances: what things are made of and how they change", "Why does an iron gate go rusty but a plastic one does not?"],
             ["Physics", "energy, forces, motion, light, sound and electricity", "Why does a metal spoon get hot in a bowl of soup?"],
             ["Earth science", "rocks, oceans, volcanoes, earthquakes and the weather (meteorology)", "Why do some places have earthquakes?"],
             ["Astronomy", "space: the Sun, planets, moons and stars", "Why can we see the Moon in the daytime?"]],
      then=["Real problems often need **several areas together**. To design a new bicycle helmet you need physics (forces in a crash) and chemistry (the materials)."]),
    Y("Which area of science?",
      grid("s7u01r11", "Sort each question into the area of science that would study it.", ["Biology", "Chemistry", "Physics", "Astronomy"],
           [("How fast does sound travel through water?", "Physics"), ("Why do bees visit some flowers more than others?", "Biology"),
            ("What happens to sugar when it dissolves in tea?", "Chemistry"), ("Why does Mars look red in the night sky?", "Astronomy")],
           "Ask: is it about living things, substances, energy and forces, or space?",
           "Sound is energy (physics); bees and flowers are living things (biology); dissolving is a change in substances (chemistry); Mars is a planet in space (astronomy).")),
    I("Scientists at work today",
      "Scientists do not only work in laboratories. Here are four of them – notice which area of science each one uses.",
      fig={"kind": "sciJobs"},
      table=[["Scientist", "What they do", "Area of science"],
             ["Water scientist", "tests river water for harmful substances before it reaches homes", "Chemistry"],
             ["Crop scientist", "breeds rice plants that can grow in salty or dry soil", "Biology"],
             ["Seismologist", "records how the ground shakes to give early warnings of earthquakes", "Earth science (and physics)"],
             ["Sound engineer", "designs walls that stop traffic noise reaching a school", "Physics"]]),
    I("Scientists build on each other's work",
      "Science is done by people from every part of the world, and each discovery helps the next one.",
      fig={"kind": "sciTimeline"},
      table=[["Scientist", "When and where", "What they did"],
             ["Ibn al-Haytham", "about 1000 years ago, Egypt and Iraq", "showed that we see objects because light travels from them into our eyes, and tested his ideas with experiments"],
             ["Marie Curie", "early 1900s, France", "discovered new radioactive elements; her work helped doctors to use radiation"],
             ["Rosalind Franklin", "1950s, England", "took X-ray pictures that showed DNA has a spiral (helix) shape"],
             ["Tu Youyou", "1970s, China", "found a new medicine for malaria from a plant used in traditional medicine"]],
      then=["None of them started from nothing: each used the ideas, instruments and results of scientists before them. "
            "This is why scientists **share** their results – so that others can check them and build on them."]),
    Y("Building on earlier work",
      mcq("s7u01r12", "Why do scientists publish their results for other people to read?",
          [("So that other scientists can check the results and build on them.", True, "Yes – shared results can be tested again and used for new discoveries."),
           ("So that nobody else needs to do any more experiments.", False, "Science never stops: new evidence can change our ideas."),
           ("Because results are only true if they are printed.", False, "Results are trusted because they can be checked, not because they are printed."),
           ("So that they become famous.", False, "Some do become famous, but that is not the reason science depends on sharing.")],
          "Think about what the next scientist needs.", "Sharing lets other scientists repeat the work, check it, and use it as a starting point.")),
    dict(X("Science is not just a list of facts",
      "Some people think science is only facts to learn by heart.",
      "But science is also a **way of finding out**. When new evidence is found, scientists change their ideas – that is a strength of science, not a weakness.",
      "Example: people once believed the Sun moved around the Earth. Careful observations of the planets showed that the Earth moves around the Sun."), fig={"kind": "sciModels"}),
    K("Key points",
      "**Science** is the study of how the natural world works; things we observe happening are **phenomena**.",
      "Science has two parts: **what we know** and **how we find out more**.",
      "Main areas: **biology**, **chemistry**, **physics**, **Earth science** and **astronomy** – real problems often need several.",
      "Science has helped us (electricity, materials, transport, medicine) but has also caused problems that science can help to solve.",
      "Scientists all over the world **build on each other's work** and share results so they can be checked."),
    book=BK(
        [("science", "the study of how the natural world works"), ("phenomenon", "something we can observe happening (plural: phenomena)"),
         ("biology", "the study of living things"), ("chemistry", "the study of substances and how they change"),
         ("physics", "the study of energy, forces, motion, light, sound and electricity"), ("Earth science", "the study of rocks, oceans and the weather"),
         ("astronomy", "the study of space"), ("global warming", "the rise in the Earth's average temperature")],
        [], [],
        [Ex("Which area of science would study each of these?",
            ("why a cut on your knee heals", "biology"), ("why a firework gives out light and sound", "chemistry (the reaction) and physics (light and sound)"),
            ("how far away the nearest star is", "astronomy"), ("why salt melts ice on a road", "chemistry")),
         Ex("Name **two** ways science has improved people's lives, and **one** problem that it has helped to cause.",
            ans="For example: electricity in homes; vaccines that stop diseases. Problem: for example, plastic waste or air pollution from transport."),
         Ex("A wildlife scientist wants to find out why fewer frogs live in a pond than ten years ago.",
            ("Which area of science is she mainly using?", "biology"),
            ("Give one other area of science that could help her, and say how.", "for example chemistry – testing the pond water for harmful substances")),
         Ex("Tu Youyou used an old book of traditional medicine to find a plant to test. Explain how this shows scientists building on earlier work.",
            ans="She started from knowledge recorded by people long before her, then tested it with experiments to make a new medicine.", think=True),
         Ex("Amira says: 'Science is finished – we already know everything.' Do you agree? Give a reason.",
            ans="No: there are still many unanswered questions, and new evidence can change our ideas.", think=True)],
        ["say what science is and give an example of a phenomenon", "name the main areas of science and what each studies",
         "describe ways science helps us and problems it has caused", "explain why scientists share and build on each other's work"],
        look=["the two parts of science", "the five areas of study and an example question for each"],
        note="Read it after the video: the key words, the areas of study and the practice on paper (answers at the back)."),
)
